window.docContents[97].resolve({"/#PropertyKindCalculus-Blueprint--Extensivity":{"contents":"Dybkær §13.5 distinguishes extensive kinds (whose value over a whole is the sum\nover disjoint parts) from kinds where that fails. This is a quantified arithmetic\nlaw over the mereology of systems — again something a description logic cannot\nstate. It is now realized, sorry-free, in the Mathlib-free Extensivity module:\nthe decomposition mereology, the Extensive predicate, the induction that lifts a\nsingle split to the whole tree, and the volume-on-mixing counterexample.\n\n\n\n","context":"PropertyKindCalculus Blueprint","header":"9. Extensivity","id":"/#PropertyKindCalculus-Blueprint--Extensivity"}});